Biography documentary cover card. 6s, 1920x1080, SILENT. Clean portrait image as background with newspaper/film grain texture, duotone treatment, Ken Burns push,. The background image has NO text — all text comes from HTML overlay only
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Inter:wght@300;400&display=swap" rel="stylesheet">
<style>
root{--oxblood:#963f43;--ivory:#e7e0d4;--muted:#9b948a;}
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#0b0d0e;}
#scene{position:relative;}
/* portrait base */
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;z-index:1
transform-origin:50% 42%
}
/* duotone shadow layer — cool blue multiply */
#d1{position:absolute;top:0;left:0;width:100%;height:100%;z-index:2;background:#1a2a4a;mix-blend-mode:multiply;opacity:0.50;}
/* duotone highlight layer — warm screen */
#d2{position:absolute;top:0;left:0;width:100%;height:100%;z-index:3;background:#e8dcc8;mix-blend-mode:screen;opacity:0.14;}
/* newspaper halftone dot grid */
#grain{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:4
background-image:radial-gradient(circle,rgba(200,180,140,0.07) 1px,transparent 1px)
background-size:5px 5px
pointer-events:none
}
/* subtle horizontal scan lines */
#lines{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:5
background:repeating-linear-gradient(
0deg
transparent
transparent 3px
rgba(0,0,0,0.06) 3px
rgba(0,0,0,0.06) 4px
)
pointer-events:none
}
/* bottom vignette for text legibility */
#grad{
position:absolute;bottom:0;left:0;width:100%;height:60%;z-index:6
background:linear-gradient(to top,rgba(0,0,0,0.90) 0%,rgba(0,0,0,0.55) 45%,transparent 100%)
}
/* title lock-up — bottom left */
#lockup{
position:absolute;bottom:88px;left:88px;z-index:10
display:flex;flex-direction:row;align-items:flex-end;gap:22px
opacity:0
}
#vline{width:2px;height:0;background:var(--oxblood);flex-shrink:0;margin-bottom:4px;}
#tcol{display:flex;flex-direction:column;gap:5px;}
#name{
font-family:'Playfair Display',Georgia,serif
font-size:70px;font-weight:700
color:var(--ivory);letter-spacing:0.06em;line-height:1;opacity:0
}
#sub{
font-family:'Inter',sans-serif;font-size:17px;font-weight:300
color:var(--muted);letter-spacing:0.32em;text-transform:uppercase;opacity:0
}
#meta{
font-family:'Inter',sans-serif;font-size:13px;font-weight:400
color:var(--oxblood);letter-spacing:0.28em;text-transform:uppercase;opacity:0;margin-top:1px
}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{heroImg}}" alt="">
<div id="d1"></div>
<div id="d2"></div>
<div id="grain"></div>
<div id="lines"></div>
<div id="grad"></div>
<div id="lockup">
<div id="vline"></div>
<div id="tcol">
<div id="name">BENEDICT CUMBERBATCH</div>
<div id="sub">A STAR IN FOCUS</div>
<div id="meta">LONDON · 1976</div>
</div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
/* Ken Burns — animate via GSAP for precision */
tl.fromTo('#bg'
{scale:1.0, transformOrigin:'50% 42%'}
{scale:1.06, duration:6, ease:'none'}
0)
/* lockup appear */
tl.to('#lockup',{opacity:1,duration:0.01},0.55)
/* vertical line sweeps up */
tl.to('#vline',{height:132,duration:0.65,ease:'expo.out'},0.55)
/* name slides in from left */
tl.to('#name',{opacity:1,x:0,duration:0.65,ease:'power3.out',startAt:{opacity:0,x:-18}},0.9)
/* sub fades in */
tl.to('#sub', {opacity:1,duration:0.4,ease:'power2.out'},1.48)
/* meta fades in */
tl.to('#meta',{opacity:1,duration:0.4,ease:'power2.out'},1.75)
/* exit */
tl.to('#lockup',{opacity:0,duration:0.45,ease:'power2.in'},5.35)
})
</script>
</body>
</html>
